package main

import (
	"encoding/json"
	"io"
	"log"
	"sync"

	maelstrom "github.com/jepsen-io/maelstrom/demo/go"
)

// log is a single append-only log (topic-partition). Offsets are dense and
// start at zero: the value at index i has offset i.
type log struct {
	entries      []json.RawMessage
	committed    int64
	hasCommitted bool
}

type server struct {
	mu   sync.Mutex
	logs map[string]*log
}

func newServer() *server {
	return &server{logs: make(map[string]*log)}
}

func (s *server) logFor(key string) *log {
	l := s.logs[key]
	if l == nil {
		l = &log{}
		s.logs[key] = l
	}
	return l
}

type sendReq struct {
	Type  string          `json:"type"`
	MsgID int             `json:"msg_id"`
	Key   string          `json:"key"`
	Msg   json.RawMessage `json:"msg"`
}

type pollReq struct {
	Type    string           `json:"type"`
	MsgID   int              `json:"msg_id"`
	Offsets map[string]int64 `json:"offsets"`
}

type commitReq struct {
	Type    string           `json:"type"`
	MsgID   int              `json:"msg_id"`
	Offsets map[string]int64 `json:"offsets"`
}

type listReq struct {
	Type  string   `json:"type"`
	MsgID int      `json:"msg_id"`
	Keys  []string `json:"keys"`
}

func pair(offset int64, value json.RawMessage) [2]any {
	return [2]any{offset, value}
}

func main() {
	// The library logs every message to stderr; at 1000 ops/s that is a lot of
	// useless I/O. Keep stderr quiet.
	log.SetOutput(io.Discard)

	n := maelstrom.NewNode()
	s := newServer()

	n.Handle("send", func(msg maelstrom.Message) error {
		var req sendReq
		if err := json.Unmarshal(msg.Body, &req); err != nil {
			return err
		}

		// Store a copy of the raw value so its exact JSON representation is
		// preserved no matter where the original message buffer lives.
		value := make(json.RawMessage, len(req.Msg))
		copy(value, req.Msg)

		s.mu.Lock()
		l := s.logFor(req.Key)
		offset := int64(len(l.entries))
		l.entries = append(l.entries, value)
		s.mu.Unlock()

		return n.Reply(msg, map[string]any{
			"type":   "send_ok",
			"offset": offset,
		})
	})

	n.Handle("poll", func(msg maelstrom.Message) error {
		var req pollReq
		if err := json.Unmarshal(msg.Body, &req); err != nil {
			return err
		}

		msgs := make(map[string][][2]any)
		s.mu.Lock()
		for key, start := range req.Offsets {
			l := s.logs[key]
			if l == nil || len(l.entries) == 0 {
				continue
			}
			if start < 0 {
				start = 0
			}
			if start >= int64(len(l.entries)) {
				continue
			}
			// Return every message from the requested offset onward. Clients
			// poll again from the next offset, so nothing is ever skipped.
			pairs := make([][2]any, 0, int64(len(l.entries))-start)
			for i := start; i < int64(len(l.entries)); i++ {
				pairs = append(pairs, pair(i, l.entries[i]))
			}
			msgs[key] = pairs
		}
		s.mu.Unlock()

		return n.Reply(msg, map[string]any{
			"type": "poll_ok",
			"msgs": msgs,
		})
	})

	commit := func(msg maelstrom.Message) error {
		var req commitReq
		if err := json.Unmarshal(msg.Body, &req); err != nil {
			return err
		}

		s.mu.Lock()
		for key, offset := range req.Offsets {
			l := s.logFor(key)
			l.committed = offset
			l.hasCommitted = true
		}
		s.mu.Unlock()

		return n.Reply(msg, map[string]any{"type": "commit_offsets_ok"})
	}
	n.Handle("commit_offsets", commit)

	list := func(msg maelstrom.Message) error {
		var req listReq
		if err := json.Unmarshal(msg.Body, &req); err != nil {
			return err
		}

		offsets := make(map[string]int64)
		s.mu.Lock()
		for _, key := range req.Keys {
			if l := s.logs[key]; l != nil && l.hasCommitted {
				offsets[key] = l.committed
			}
		}
		s.mu.Unlock()

		return n.Reply(msg, map[string]any{
			"type":    "list_committed_offsets_ok",
			"offsets": offsets,
		})
	}
	n.Handle("list_committed_offsets", list)
	// Older descriptions of the protocol call this fetch_committed_offsets.
	n.Handle("fetch_committed_offsets", list)

	n.Handle("status", func(msg maelstrom.Message) error {
		return n.Reply(msg, map[string]any{"type": "status_ok"})
	})

	if err := n.Run(); err != nil {
		log.Println(err)
	}
}

